contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, string calldata description) external {
        bool isAdminBefore = c.isAdmin(caller);
        require(isAdminBefore, "Caller is not admin, skip test scenario where rule holds");

        vm.prank(caller);
        c.newEmergencyOracle(description);

        assert(c.isAdmin(caller));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address admin, string calldata desc) public payable {
        require(true);
        bool reverted; try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        assert(!c.isAdmin(admin) || !reverted);
    }
}

